 // src/services/uploadService.js
import { supabase } from '../lib/supabase'

/**
 * Upload an image or video to Supabase Storage
 * @param {File} file - The file to upload
 * @param {string} userId - The user ID for folder organization
 * @param {string} bucket - The storage bucket name (default: 'post-images')
 * @returns {Promise<string>} - The public URL of the uploaded file
 */
export async function uploadImage(file, userId, bucket = 'post-images') {
    if (!file) return null
    
    // Validate file type
    if (!file.type.startsWith('image/') && !file.type.startsWith('video/')) {
        throw new Error('File must be an image or video')
    }
    
    // Validate file size
    const maxSize = file.type.startsWith('video/') ? 50 * 1024 * 1024 : 10 * 1024 * 1024
    if (file.size > maxSize) {
        throw new Error(`File must be less than ${maxSize / (1024 * 1024)}MB`)
    }
    
    // ✅ Generate a truly unique filename - never overwrite
    const fileExt = file.name.split('.').pop()
    const timestamp = Date.now()
    const randomString = Math.random().toString(36).substring(2, 15)
    const uniqueId = crypto.randomUUID ? crypto.randomUUID() : `${timestamp}-${randomString}`
    const fileName = `${userId}/${uniqueId}.${fileExt}`
    
    console.log('📤 Uploading file:', fileName)
    console.log('📦 Bucket:', bucket)
    console.log('📏 File size:', file.size)
    
    // ✅ First, check if file exists and generate new name if needed
    let finalFileName = fileName
    let exists = true
    let attempt = 0
    const maxAttempts = 10
    
    while (exists && attempt < maxAttempts) {
        const { data: existingFile } = await supabase.storage
            .from(bucket)
            .list(userId, {
                limit: 1,
                offset: 0,
                sortBy: { column: 'name', order: 'asc' }
            })
        
        // Check if our file exists
        const fileExists = existingFile?.some(f => f.name === finalFileName.split('/').pop())
        
        if (!fileExists) {
            exists = false
        } else {
            // Generate a new name
            const newId = crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`
            finalFileName = `${userId}/${newId}.${fileExt}`
            attempt++
        }
    }
    
    const { error } = await supabase.storage
        .from(bucket)
        .upload(finalFileName, file, {
            cacheControl: 'public, max-age=31536000',
            upsert: false,
            contentType: file.type
        })
    
    if (error) {
        console.error('❌ Upload error:', error)
        throw new Error('Failed to upload file: ' + error.message)
    }
    
    const { data } = supabase.storage
        .from(bucket)
        .getPublicUrl(finalFileName)
    
    console.log('✅ Upload successful, URL:', data.publicUrl)
    
    return data.publicUrl
}

/**
 * Delete a file from Supabase Storage
 */
export async function deleteImage(filePath, bucket = 'post-images') {
    if (!filePath) return
    
    try {
        const url = new URL(filePath)
        const path = url.pathname.split('/').slice(3).join('/')
        
        const { error } = await supabase.storage
            .from(bucket)
            .remove([path])
        
        if (error) {
            console.error('Delete error:', error)
        }
    } catch (error) {
        console.error('Error deleting image:', error)
    }
}

/**
 * Upload a profile avatar
 */
export async function uploadAvatar(file, userId) {
    return uploadImage(file, userId, 'avatars')
}
